compile.workshop:
variables {
    global:
        0: g
}

//Optimize for size enabled
//Strict optimizations enabled
rule ("before include") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 3);
    }
}

//Optimizations disabled
rule ("child rule") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, Subtract(3, 1));
    }
}

//Optimizations enabled
//Strict optimizations disabled
rule ("child rule 2") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 9);
    }
}

rule ("after include") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 6);
    }
}

